mapper.select:
select r.record_id, r.asset_id, r.record_type, r.content, r.before_status, r.after_status, r.operator, r.create_time,
       a.asset_code, a.asset_name
from biz_asset_record r
	left join biz_asset_info a on a.asset_id = r.asset_id


		AND r.asset_id = #{assetId}


		AND a.asset_code like concat('%', #{assetCode}, '%')


		AND a.asset_name like concat('%', #{assetName}, '%')


		AND r.record_type = #{recordType}


		AND r.create_time >= #{params.beginCreateTime}


		AND r.create_time <= #{params.endCreateTime}


order by r.create_time desc, r.record_id desc

mapper.insert:
insert into biz_asset_record(
	asset_id, record_type, content, before_status, after_status, operator, create_time
)values(
	#{assetId}, #{recordType}, #{content}, #{beforeStatus}, #{afterStatus}, #{operator}, #{createTime}
)
